-- 129: Original BrillaPrep WASSCE Applied Electricity syllabus evidence beta questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_011', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', 'What does a capacitor store?', 'multiple_choice', '["A. A continuous supply of fuel","B. Only magnetic poles","C. Electric charge and energy in an electric field","D. Mechanical torque without a field"]', 'C', 'Separated conductors and a dielectric allow charge to accumulate, with energy stored in the electric field between them. Therefore the correct answer is C: Electric charge and energy in an electric field.', 'medium', 1, 1, 90, 'st_was_elect_3', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_012', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', 'What is the unit of capacitance?', 'multiple_choice', '["A. Henry","B. Weber","C. Tesla","D. Farad"]', 'D', 'Capacitance is charge stored per unit potential difference and is measured in farads, commonly expressed in microfarads or smaller units. Therefore the correct answer is D: Farad.', 'hard', 2, 2, 90, 'st_was_elect_3', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_013', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', 'How does capacitive reactance change when frequency increases?', 'multiple_choice', '["A. It decreases","B. It increases linearly","C. It remains constant","D. It becomes resistance only"]', 'A', 'Capacitive reactance is Xc = 1 divided by 2πfC, so higher frequency produces less opposition from a given capacitor. Therefore the correct answer is A: It decreases.', 'easy', 1, 1, 90, 'st_was_elect_3', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_014', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', 'What is impedance in an alternating-current circuit?', 'multiple_choice', '["A. The direct-current charge of a battery","B. The combined opposition of resistance and reactance","C. Only the physical size of a conductor","D. Power multiplied by time"]', 'B', 'Impedance accounts for resistance and frequency-dependent reactance and is represented in ohms, often with magnitude and phase. Therefore the correct answer is B: The combined opposition of resistance and reactance.', 'medium', 2, 2, 90, 'st_was_elect_3', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_015', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', 'Why is a high power factor generally desirable for an AC load?', 'multiple_choice', '["A. It makes voltage and frequency irrelevant","B. It eliminates all energy loss","C. It reduces current required for a given real power","D. It causes every load to become capacitive"]', 'C', 'When power factor is closer to unity, less current is needed to deliver the same useful power, reducing conductor and system losses. Therefore the correct answer is C: It reduces current required for a given real power.', 'hard', 3, 3, 90, 'st_was_elect_3', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_016', 'topic_was_elect_4', 'subj_wassce_elect_app', 'exam_wassce', 'What happens around a conductor carrying current?', 'multiple_choice', '["A. Its resistance must become zero","B. All nearby metals become permanent magnets","C. Voltage can no longer be measured","D. A magnetic field is produced"]', 'D', 'Moving electric charge produces a magnetic field whose direction around a straight conductor follows the right-hand grip rule. Therefore the correct answer is D: A magnetic field is produced.', 'easy', 2, 2, 90, 'st_was_elect_4', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_017', 'topic_was_elect_4', 'subj_wassce_elect_app', 'exam_wassce', 'What is electromagnetic induction?', 'multiple_choice', '["A. Production of an emf when magnetic flux linkage changes","B. Creation of energy without a source","C. Permanent charging of every iron core","D. Conversion of resistance directly into mass"]', 'A', 'Faraday’s law relates induced emf to the rate of change of magnetic flux linkage through a circuit. Therefore the correct answer is A: Production of an emf when magnetic flux linkage changes.', 'medium', 1, 1, 90, 'st_was_elect_4', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_018', 'topic_was_elect_4', 'subj_wassce_elect_app', 'exam_wassce', 'Why is a transformer core laminated?', 'multiple_choice', '["A. To increase winding resistance deliberately","B. To reduce eddy-current losses","C. To stop magnetic flux entirely","D. To convert AC directly into DC"]', 'B', 'Thin insulated laminations interrupt circulating currents in the core, reducing heating and wasted power. Therefore the correct answer is B: To reduce eddy-current losses.', 'hard', 2, 2, 90, 'st_was_elect_4', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_019', 'topic_was_elect_4', 'subj_wassce_elect_app', 'exam_wassce', 'An ideal transformer has 100 primary turns and 20 secondary turns with 240 V applied. What is the secondary voltage?', 'multiple_choice', '["A. 12 V","B. 120 V","C. 48 V","D. 1200 V"]', 'C', 'For an ideal transformer, Vs divided by Vp equals Ns divided by Np. Thus 240 multiplied by 20 over 100 equals 48 volts. Therefore the correct answer is C: 48 V.', 'easy', 1, 1, 90, 'st_was_elect_4', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_elect_b001_020', 'topic_was_elect_4', 'subj_wassce_elect_app', 'exam_wassce', 'Why does a transformer require a changing magnetic flux?', 'multiple_choice', '["A. Steady DC automatically produces continuous secondary voltage","B. Flux must remain zero for energy transfer","C. The core supplies unlimited electrical energy","D. A changing flux is needed to induce emf in the secondary winding"]', 'D', 'Mutual induction depends on changing flux linkage, which is why ordinary transformers operate with alternating rather than steady direct current. Therefore the correct answer is D: A changing flux is needed to induce emf in the secondary winding.', 'medium', 3, 3, 90, 'st_was_elect_4', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Ghana Applied Electricity evidence; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2023/12/Technical17.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_elect_b001_011' AND 'q_was_elect_b001_020';
